let cached = null;
const QUERY_STOP_WORDS = new Set(["about", "and", "are", "can", "does", "for", "from", "have", "how", "our", "the", "this", "use", "what", "when", "with", "you"]);
const tokens = (text) => [...new Set((text.toLowerCase().match(/[a-z0-9]{3,}/g) ?? []).filter(token => !QUERY_STOP_WORDS.has(token)))];
export function policyArchive() {
    if (cached)
        return cached;
    const text = gunzipSync(Buffer.from(ARCHIVE_GZIP_BASE64, "base64")).toString("utf8");
    const records = text.split("\n========================================================================\nFILE: ").slice(1).map(block => {
        const header = block.match(/^(.+?)\n=+\nRule Record ID: (ASU-R-\d{3})\b/m);
        if (!header)
            throw new Error("Policy archive has a record without a file code and record ID.");
        const source = POLICY_CATALOG.find(record => record.recordId === header[2]);
        if (!source || source.sourceFileCode !== header[1])
            throw new Error(`Policy archive does not match catalog record ${header[2]}.`);
        const marker = "BEGIN EXTRACTED TEXT\n";
        const at = block.indexOf(marker);
        if (at < 0)
            throw new Error(`Policy archive is missing text for ${header[2]}.`);
        return { ...source, detail: block.slice(at + marker.length).trim() };
    });
    if (records.length !== POLICY_SOURCE_COUNT)
        throw new Error(`Expected ${POLICY_SOURCE_COUNT} detailed policy records, found ${records.length}.`);
    cached = records;
    return cached;
}
/** Retrieves only the most relevant archive records, capped before an AI request is built. */
export function searchPolicyArchive(question, limit = 3, maxChars = 12000) {
    const query = tokens(question);
    if (!query.length)
        return [];
    const ranked = policyArchive().map(record => {
        const title = `${record.officialName} ${record.whatItCovers}`.toLowerCase();
        const detail = record.detail.toLowerCase();
        const score = query.reduce((sum, token) => sum + (title.includes(token) ? 12 : 0) + (detail.includes(token) ? 1 : 0), 0);
        return { record, score };
    }).filter(hit => hit.score > 0).sort((a, b) => b.score - a.score || a.record.recordId.localeCompare(b.record.recordId));
    const out = [];
    let used = 0;
    for (const { record } of ranked.slice(0, limit)) {
        // The caller receives the full matched record, but budget its eventual AI excerpt rather than letting one
        // long source prevent every other relevant record from being selected.
        const size = Math.min(record.detail.length, Math.floor(maxChars / Math.max(1, limit)));
        if (out.length && used + size > maxChars)
            continue;
        out.push(record);
        used += size;
    }
    return out;
}
